sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_progress;
uniform float amzp_colorMode;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_alphaComp;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_complexity;
uniform float amzp_density;
uniform float amzp_switchSpeed;
uniform float2 amzp_cellSize;
uniform float amzp_skew;
uniform float amzp_soft;
uniform float amzp_pixel;
uniform float amzp_stripes;
uniform float amzp_seed;
layout(color) uniform half4 amzp_fgColor;
layout(color) uniform half4 amzp_bgColor;
layout(color) uniform half4 amzp_colA;
layout(color) uniform half4 amzp_colB;
uniform float amzp_hueSpeed;
uniform float amzp_displace;
uniform float amzp_rgbSplit;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float2 nmStd(float2 p, float pxk) {
        float z = max(amzp_scale * 2.0, 0.002);
        p -= amzp_position * pxk;
        p = nmRot(p, -radians(amzp_angle));
        return p / (z * max(amzp_stretch, float2(0.01)));
    }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        if (int(amzp_blendMode) == 0) return f;
        if (int(amzp_blendMode) == 1) return float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        if (int(amzp_blendMode) == 2) return float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        return f + b * (1.0 - f.a);
    }
    float4 hash42(float2 p) {
        float4 p4 = fract(float4(p.xyxy + amzp_seed * 0.731) * float4(0.1031, 0.1030, 0.0973, 0.1099));
        p4 += dot(p4, p4.wzxy + 33.33);
        return fract((p4.xxyz + p4.yzzw) * p4.zywx);
    }
    float qz(float x, float p) { return floor(x / p) * p; }
    float tm() { return (amzp_autop>0.5) ? amzp_progress + time * amzp_autoSpeed : amzp_progress; }
    float3 hue(float h) { return clamp(abs(mod(h * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0); }
    float4 pat(float2 uv, float t) {
        float4 h = hash42(floor(uv));
        uv.y += uv.x * (h.x - 0.5) * amzp_skew;
        uv *= max(amzp_cellSize, float2(0.01));
        uv += floor(t * amzp_switchSpeed) * amzp_cellSize * h.y;
        float s = 1.0;
        float4 o = float4(1.0);
        for (int i = 1; i <= 20; i++) {
            if (float(i) > amzp_complexity) break;
            float fi = float(i);
            float2 c = floor(uv + fi);
            float4 hh = hash42(c);
            float2 p = fract(uv + fi + qz(t, hh.z + 1.0) * hh.y);
            uv += p * hh.z * hh.xy * float2(s, 2.0);
            s = -s * (1.1 + hh.y);
            if (hh.w > amzp_density) o *= hh;
        }
        return o;
    }
    void amzRender() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 tex = amzTexture(0, amzScreenNorm());
        float px = pxs();
        float t = tm();
        float2 fp = (uv - 0.5) * W;
        if (amzp_pixel > 0.0) fp = (floor(fp / (amzp_pixel * px)) + 0.5) * amzp_pixel * px;
        float2 p = nmStd(float2(fp.x, -fp.y), px) / (0.5 * W.y) * 0.32;
        float4 o = pat(p, t);
        float e = max(amzp_soft, 0.001);
        float4 m = smoothstep(float4(0.5 - e), float4(0.5 + e), o);
        float stripe = mix(1.0, mod(floor(amzScreenNorm().x * screen.zw.x), 3.0) / 2.0, clamp(amzp_stripes, 0.0, 1.0));
        float cover = max(max(m.r, m.g), m.b);
        float2 dsp = (o.xy - 0.5) * 2.0 * amzp_displace * cover;
        float2 su = uv + dsp;
        float2 sd = float2(amzp_rgbSplit * cover, 0.0);
        float4 lr = amzTexture(0, l2s(su + sd));
        float4 lg = amzTexture(0, l2s(su));
        float4 lb = amzTexture(0, l2s(su - sd));
        float4 lay = amzp_displace > 0.0 || amzp_rgbSplit > 0.0 ? float4(lr.r, lg.g, lb.b, max(max(lr.a, lg.a), lb.a)) : tex;
        lay = mix(tex, lay, step(0.001, amzp_displace + amzp_rgbSplit * cover));
        float4 bg = float4(amzp_bgColor.rgb * amzp_bgColor.a, amzp_bgColor.a);
        float4 fx;
        if (int(amzp_colorMode) == 0) {
            fx = float4(m.rgb * stripe, 1.0);
            fx = mix(bg, fx, m.a);
        } else if (int(amzp_colorMode) == 1) {
            fx = mix(bg, float4(amzp_fgColor.rgb * amzp_fgColor.a, amzp_fgColor.a) * float4(float3(stripe), 1.0), m.r);
        } else if (int(amzp_colorMode) == 2) {
            float4 a = float4(amzp_colA.rgb * amzp_colA.a, amzp_colA.a), b = float4(amzp_colB.rgb * amzp_colB.a, amzp_colB.a);
            float4 dc = mix(a, b, m.g);
            fx = mix(bg, dc * float4(float3(stripe), 1.0), m.r);
        } else if (int(amzp_colorMode) == 3) {
            float2 jump = (o.zw - 0.5) * 0.5;
            float4 lc = amzTexture(0, l2s(fract(su + jump)));
            fx = mix(lay, lc * float4(float3(stripe), 1.0), cover);
        } else {
            float3 un = lay.a > 0.0001 ? lay.rgb / lay.a : float3(0.0);
            float l = dot(un, float3(0.299, 0.587, 0.114));
            float3 hc = hue(fract(o.x + t * amzp_hueSpeed)) * (0.35 + 0.65 * l);
            fx = mix(lay, float4(hc * stripe * lay.a, lay.a), cover);
        }
        float4 base = amzp_displace > 0.0 || amzp_rgbSplit > 0.0 ? lay : tex;
        amzOutput = nmBlend(base, fx) * tex.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
